import type { PluginConfig, PluginData } from "../types/index"
import { personality16Plugin } from "./16personalities/index"
import { aniListPlugin } from "./anilist/index"
import { githubPlugin } from "./github/index"
import { githubRepoPlugin } from "./github_repo/index"
import { lastFmPlugin } from "./lastfm/index"
import { lyftaPlugin } from "./lyfta/index"
import { myAnimeListPlugin } from "./myanimelist/index"
import type { EssentialPluginConfig } from "./shared/types/base"
import type { Plugin } from "./shared/types/plugin"
import { steamPlugin } from "./steam/index"
import { duolingoPlugin } from "./duolingo/index"
import { codewarsPlugin } from "./codewars/index"
import { devToPlugin } from "./devto/index"
import { codeforcesPlugin } from "./codeforces/index"
import { stackoverflowPlugin } from "./stackoverflow/index"
import { websitesPlugin } from "./websites/index"

export class PluginManager {
  private static instance: PluginManager
  private plugins: Map<string, Plugin> = new Map()
  private activePlugins: Set<string> = new Set()

  private constructor() {
    // Registrar plugins disponíveis
    this.register(githubPlugin)
    this.register(githubRepoPlugin)
    this.register(lastFmPlugin)
    this.register(myAnimeListPlugin)
    this.register(aniListPlugin)
    this.register(personality16Plugin)
    this.register(lyftaPlugin)
    this.register(steamPlugin)
    this.register(duolingoPlugin)
    this.register(codewarsPlugin)
    this.register(devToPlugin)
    this.register(codeforcesPlugin)
    this.register(stackoverflowPlugin)
    this.register(websitesPlugin)
  }

  public static getInstance(): PluginManager {
    if (!PluginManager.instance) {
      PluginManager.instance = new PluginManager()
    }
    return PluginManager.instance
  }

  public register<T extends PluginConfig = PluginConfig, D extends PluginData = PluginData>(
    plugin: Plugin<T, D>
  ): void {
    // Type assertion necessário devido à estrutura genérica dos plugins
    // Convertemos via unknown para permitir diferentes tipos de config
    this.plugins.set(plugin.name, plugin as unknown as Plugin)
  }

  public get(name: string): Plugin | undefined {
    return this.plugins.get(name)
  }

  public getAll(): Plugin[] {
    return Array.from(this.plugins.values())
  }

  /**
   * Inicializa plugins ativos baseado na configuração
   */
  public initializeActivePlugins(pluginsConfig: Record<string, { enabled?: boolean }>): void {
    this.activePlugins.clear()

    for (const [name, config] of Object.entries(pluginsConfig)) {
      if (config.enabled && this.plugins.has(name)) {
        this.activePlugins.add(name)
      }
    }
  }

  /**
   * Retorna lista de plugins ativos
   */
  public getActivePlugins(): Array<[string, Plugin]> {
    return Array.from(this.activePlugins)
      .map((name) => {
        const plugin = this.plugins.get(name)
        return plugin ? [name, plugin] : null
      })
      .filter((item): item is [string, Plugin] => item !== null)
  }

  /**
   * Busca dados de um plugin específico
   */
  public async fetchPluginData(
    name: string,
    config: Plugin["config"],
    dev = false,
    essentialConfig?: EssentialPluginConfig,
    previewMode = false
  ): Promise<PluginData> {
    const plugin = this.get(name)
    if (!plugin) {
      throw new Error(`Plugin ${name} not found`)
    }
    return await plugin.fetchData(config, dev, essentialConfig, previewMode)
  }

  /**
   * Computes total SVG height by summing calculateHeight() across all enabled plugins.
   * Replaces Playwright-based height measurement for Cloudflare Worker compatibility.
   * Adds a 24px safety buffer to absorb minor font-rendering and layout edge cases.
   */
  public calculateTotalHeight(
    pluginsConfig: Record<string, Plugin["config"]>,
    pluginsData: Record<string, PluginData>,
    size: "half" | "full" = "half"
  ): number {
    let total = 0
    for (const [name, config] of Object.entries(pluginsConfig)) {
      if (!config.enabled) continue
      const plugin = this.get(name)
      if (!plugin) continue
      const data = pluginsData[name]
      if (!data) continue
      const sectionHeight = plugin.calculateHeight(config, data, size)
      // Defend against a plugin's calculateHeight() returning NaN/negative (e.g. from a
      // malformed count) -- that must never propagate into the SVG's overall height.
      if (Number.isFinite(sectionHeight) && sectionHeight > 0) total += sectionHeight
    }
    return total > 0 ? total + 24 : 0
  }

  /**
   * Busca dados de todos os plugins ativos
   */
  public async fetchAllPluginsData(
    pluginsConfig: Record<string, Plugin["config"]>,
    dev = false,
    essentialConfigs?: Record<string, EssentialPluginConfig>,
    previewMode = false
  ): Promise<Record<string, PluginData>> {
    const activePlugins = this.getActivePlugins()
    const results: Record<string, PluginData> = {}

    await Promise.all(
      activePlugins.map(async ([name, plugin]) => {
        const config = pluginsConfig[name]
        if (config) {
          try {
            // Obter essentialConfig específico do plugin (se disponível)
            const essentialConfig = essentialConfigs?.[name]
            const data = await plugin.fetchData(config, dev, essentialConfig, previewMode)
            results[name] = data
          } catch (error) {
            console.error(`Error fetching data for plugin ${name}:`, error)
            // Não adicionar ao results em caso de erro
          }
        }
      })
    )

    return results
  }
}
